import {useState} from 'react';
import {CoachCelo} from './CoachCelo';
export type Workshop = {goal:string;steps:{title:string;explain:string;example:string}[];mistake:string;challenge:{prompt:string;choices:string[];correct:number;explanation:string}};
export function LessonWorkshop({workshop,onReview}:{workshop:Workshop;onReview:()=>void}){
 const [step,setStep]=useState(0);const [choice,setChoice]=useState<number|null>(null);const [checked,setChecked]=useState(false);
 const [premium,setPremium]=useState(2);const [quantity,setQuantity]=useState(1);
 const current=workshop.steps[step];const practice=step===workshop.steps.length;
 function move(index:number){setStep(index);setChoice(null);setChecked(false);}
 return <section className="lesson-workshop" aria-label="Guided lesson">
 <p className="workshop-goal"><strong>By the end:</strong> {workshop.goal}</p>
 <nav className="workshop-route" aria-label="Teaching steps">{workshop.steps.map((s,i)=><button key={s.title} className={step===i?'selected':''} aria-current={step===i?'step':undefined} onClick={()=>move(i)}>{i+1}. {s.title}</button>)}<button className={practice?'selected':''} aria-current={practice?'step':undefined} onClick={()=>move(workshop.steps.length)}>Try a new situation</button></nav>
 {!practice&&current?<div className="workshop-columns"><div><p className="portal-eyebrow">STEP {step+1} OF {workshop.steps.length}</p><h3>{current.title}</h3><p>{current.explain}</p><section className="workshop-example"><h4>Walk through it</h4><p>{current.example}</p></section></div><CoachCelo><p><strong>Keep these separate:</strong> {workshop.mistake}</p></CoachCelo></div>:<section><h3>Use the idea in a different situation</h3><p>Practice only. This does not place an order or change your saved lesson score.</p><fieldset className="portal-question"><legend>{workshop.challenge.prompt}</legend>{workshop.challenge.choices.map((c,i)=><label key={c}><input type="radio" name="workshop-choice" checked={choice===i} onChange={()=>{setChoice(i);setChecked(false);}}/>{c}</label>)}</fieldset><button className="btn btn-primary" disabled={choice===null} onClick={()=>setChecked(true)}>Explain my answer</button>{checked&&<div className="portal-feedback" role="status"><h4>{choice===workshop.challenge.correct?'Correct. Here is the reasoning.':'Not quite. Let’s work it out.'}</h4><p>{workshop.challenge.explanation}</p></div>}
 <details className="workshop-experiment"><summary>Try the contract-cost calculator</summary><p>Change the quote and contract count. These are practice numbers, not your account or a market quote. Standard 100-share contracts only.</p><label>Option quote per share: ${premium.toFixed(2)}<input aria-label="Practice option premium" type="range" min="0.5" max="5" step="0.25" value={premium} onChange={e=>setPremium(Number(e.target.value))}/></label><label>Contracts: {quantity}<input aria-label="Practice contract count" type="range" min="1" max="5" step="1" value={quantity} onChange={e=>setQuantity(Number(e.target.value))}/></label><output aria-live="polite">${premium.toFixed(2)} × 100 × {quantity} = ${(premium*100*quantity).toFixed(2)} before fees</output><p>Doubling the contract count doubles the purchase cost. This calculator does not estimate a stop loss or recommend a quantity.</p></details>
 </section>}
 <footer className="workshop-controls"><button className="btn btn-ghost" disabled={step===0} onClick={()=>move(step-1)}>Previous step</button>{practice?<button className="btn btn-primary" onClick={onReview}>Go to the saved knowledge check</button>:<button className="btn btn-primary" onClick={()=>move(step+1)}>{step===workshop.steps.length-1?'Try a new situation':'Next step'}</button>}</footer>
 </section>;
}
